// Store active sensors in global context
if (msg.payload && msg.payload.success && msg.payload.data) {
    const sensors = msg.payload.data;
    global.set('activeSensors', sensors);

    // Initialize last values for smooth transitions
    const lastValues = {};
    sensors.forEach(sensor => {
        const mid = (sensor.minValue + sensor.maxValue) / 2;
        lastValues[sensor.sensorId] = mid;
    });
    global.set('lastSensorValues', lastValues);

    msg.payload = {
        loaded: true,
        count: sensors.length,
        sensors: sensors
    };

    node.status({fill:"green", shape:"dot", text:`${sensors.length} sensors loaded`});
} else {
    msg.payload = {
        loaded: false,
        error: 'Failed to load sensors'
    };
    node.status({fill:"red", shape:"dot", text:"Failed to load sensors"});
}

return msg;

// Retrieve active sensors from global context
const sensors = global.get('activeSensors') || [];

if (sensors.length === 0) {
    node.status({fill:"yellow", shape:"ring", text:"No sensors loaded"});
    return null;
}

node.status({fill:"green", shape:"dot", text:`Processing ${sensors.length} sensors`});

msg.payload = sensors;
return msg;

// Get sensor info from payload
const sensor = msg.payload;
const sensorId = sensor.sensorId;
const sensorName = sensor.sensorName;
const bedroomName = sensor.bedroomName;
const type = sensor.type;
const minValue = sensor.minValue;
const maxValue = sensor.maxValue;

// Get last value for this sensor
const lastValues = global.get('lastSensorValues') || {};
const lastValue = lastValues[sensorId] || (minValue + maxValue) / 2;

// Generate realistic value with smooth transitions
// Allow small variations (±2 units) from last value
const maxChange = (type === 'temperature') ? 1.5 : 3.0;
const randomChange = (Math.random() - 0.5) * 2 * maxChange;
let newValue = lastValue + randomChange;

// Ensure value stays within bounds
newValue = Math.max(minValue, Math.min(maxValue, newValue));

// Round to 2 decimal places
newValue = Math.round(newValue * 100) / 100;

// Store the new value
lastValues[sensorId] = newValue;
global.set('lastSensorValues', lastValues);

// Prepare the message for database insert
msg.payload = {
    sensor_id: sensorId,
    room_name: bedroomName,
    sensor_name: sensorName,
    value: newValue,
    timestamp: new Date().toISOString()
};

msg.topic = "INSERT INTO sensor_logs (sensor_id, room_name, sensor_name, timestamp, value) VALUES ($1, $2, $3, $4, $5)";
msg.queryParameters = [sensorId, bedroomName, sensorName, msg.payload.timestamp, newValue];

node.status({
    fill: "blue",
    shape: "dot",
    text: `${bedroomName} - ${sensorName}: ${newValue}`
});

return msg;
